  for (const y of [2, 3]) for (const x of [6, 7]) bookshelf(g, x, y, 18);
  chest(g, 3, 2, 18, "north");
  pot(g, 3, 2, 12, "potted_fern");
  lantern(g, 5, 4, 15, true);

