  const shapes = new Set(st.map((c) => c.state.shape.replace(/_(left|right)$/, "")));
  assert.ok(shapes.has("outer"), "hips have outer corners");
  assert.equal(shapes.has("inner"), wantInner, "valleys (L only) have inner corners");
  for (const c of st) {                                                    // the back faces the higher side
    if (c.state.shape.startsWith("inner")) continue;
    const [dx, dz] = DIR[c.state.facing];
    assert.ok(top(c.pos[0] + dx, c.pos[2] + dz) >= c.pos[1], `stair at ${c.pos} faces ${c.state.facing} but that side is lower`);
  }
}

